package com.securechat.admin;

import com.nimbusds.jose.jwk.JWKSet;
import com.nimbusds.jose.jwk.KeyUse;
import com.nimbusds.jose.jwk.RSAKey;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.security.GeneralSecurityException;
import java.security.KeyFactory;
import java.security.interfaces.RSAPrivateCrtKey;
import java.security.interfaces.RSAPublicKey;
import java.security.spec.PKCS8EncodedKeySpec;
import java.security.spec.RSAPublicKeySpec;
import java.util.Base64;

/** RS256 signing key loaded from a PKCS#8 PEM file (generated by scripts/gen-secrets.sh). */
public final class SigningKeys {
    private final RSAKey jwk;

    private SigningKeys(RSAKey jwk) {
        this.jwk = jwk;
    }

    public static SigningKeys fromPemFile(String file) {
        try {
            return fromPem(Files.readString(Path.of(file)));
        } catch (IOException e) {
            throw new IllegalStateException("cannot read signing key " + file, e);
        }
    }

    public static SigningKeys fromPem(String pem) {
        try {
            String b64 = pem.replaceAll("-----(BEGIN|END) PRIVATE KEY-----", "").replaceAll("\\s", "");
            KeyFactory kf = KeyFactory.getInstance("RSA");
            RSAPrivateCrtKey priv = (RSAPrivateCrtKey) kf.generatePrivate(new PKCS8EncodedKeySpec(Base64.getDecoder().decode(b64)));
            RSAPublicKey pub = (RSAPublicKey) kf.generatePublic(new RSAPublicKeySpec(priv.getModulus(), priv.getPublicExponent()));
            RSAKey key = new RSAKey.Builder(pub).privateKey(priv).keyUse(KeyUse.SIGNATURE)
                    .keyIDFromThumbprint().build();
            return new SigningKeys(key);
        } catch (GeneralSecurityException | com.nimbusds.jose.JOSEException e) {
            throw new IllegalStateException("invalid RSA private key", e);
        }
    }

    public RSAKey jwk() {
        return jwk;
    }

    /** Public JWKS only — never includes private parameters. */
    public JWKSet publicJwks() {
        return new JWKSet(jwk.toPublicJWK());
    }
}
